window.initHbRange=function(){document.querySelectorAll("[data-hb-range]").forEach(e=>{const n=e.querySelector("[data-hb-input]"),o=e.querySelectorAll("[data-hb-lens] img"),t=e.querySelector("[data-vrt-large-value]"),a=e.querySelector("[data-vrt-small-value]");if(!n)return;const i=()=>{const s=parseFloat(n.value),l=s*100;l>10&&l<100&&(l>70?(t&&(t.style.display="none"),a&&(a.style.display="block")):(a&&(a.style.display="none"),t&&(t.style.display="block"))),o.forEach(r=>{r.style.opacity=s})};n.addEventListener("input",i),i()})},document.addEventListener("DOMContentLoaded",initHbRange);
